from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
r=Path(__file__).resolve().parents[1];o=r/"phase28";rows=[];meta=[]
for f in sorted(o.glob("*_joint_*/validation_audit.json")):
 a=json.loads(f.read_text());d=json.loads((f.parent/"complete.json").read_text());assert a["status"]=="PASS";assert hashlib.sha256((f.parent/"model.pt").read_bytes()).hexdigest()==a["selected_checkpoint_sha256"];rows.extend(a["results"]);meta.append(dict(source=d["source"],weight=d["aux_weight"],epoch=d["best_epoch"],f1=100*d["best_val_f1"],initial_f1=100*d["initial_val_f1"]))
if not rows:raise SystemExit("No audited joint models")
df=pd.DataFrame(rows);prior=pd.read_csv(o/"code_prior_baselines.csv");df=df.merge(prior,on=["source","subject"],validate="many_to_one");df["signal_ce_advantage"]=df.input_shuffled_masked_ce-df.masked_ce;df["position_prior_ce_advantage"]=df.position_prior_ce-df.masked_ce;df.to_csv(o/"validation_participants.csv",index=False);summary=df.groupby(["source","weight"])[["f1","masked_ce","masked_accuracy","input_shuffled_masked_ce","position_prior_ce","signal_ce_advantage","position_prior_ce_advantage"]].mean().reset_index();summary["f1"]*=100;summary=summary.merge(pd.DataFrame(meta)[["source","weight","epoch"]],on=["source","weight"]);summary.to_csv(o/"summary.csv",index=False);selections=[]
for source,g in summary.groupby("source"):
 if len(g)!=3:continue
 winner=g.sort_values(["f1","weight"],ascending=[False,True]).iloc[0];weight=float(winner.weight);folder=o/f"{source}_joint_{weight:g}";selection=dict(source=source,selected_weight=weight,selected_directory=folder.name,checkpoint_sha256=hashlib.sha256((folder/"model.pt").read_bytes()).hexdigest(),rule="Source4person meanMacroF1 among weights0/.01/.1; tie lowerweight; each candidate includesepoch0fallback",candidates=g.to_dict("records"),source_only=True,no_target_evaluation=True);selections.append(selection);(o/f"{source}_selection.json").write_text(json.dumps(selection,indent=2))
(o/"summary_audit.json").write_text(json.dumps(dict(status="PASS",completed_configs=len(meta),complete=len(meta)==6,source_prediction_streams=len(rows),classification_and_auxiliary_recomputed=True,checkpoint_hashes_match=True,source_only=True),indent=2))
html="""<!doctype html><html lang="zh"><meta charset="utf-8"><title>修正教师联合训练</title><style>body{font:16px/1.65 system-ui;max-width:1200px;margin:30px auto}td,th{padding:6px;border-bottom:1px solid #ccc}</style><h1>修正教师的源域联合训练</h1><p>独立探索分支：VQNSP各层CLS键logit减log8，码本固定，学生编码器结构不变。原分词器双导联代码塌缩结果见<a href="../phase26/report.html">有效性审计</a>。并非官方方法的严格复现。</p><p>两个来源，各权重0/.01/.1，10轮，seed17。零权重组执行相同掩码前向、消耗相同随机数，但辅助梯度为0；梯度误差与FP32重复计算同量级。分类与辅助头、编码器从相同初始化开始。按四名源验证受试者的平均F1选epoch与权重，包含不训练回退。没有目标人群评估。</p><p>辅助CE越低越好；signal_ce_advantage是把输入窗口打乱后增加的CE；position_prior_ce_advantage是相对源拟合位置代码频率基线的CE改善。正值支持辅助模型使用输入信号，不能单独证明其更新有助于睡眠分类。</p>"""+f"<p>已独立审计{len(meta)}/6组、{len(rows)}条源预测流。</p>"+summary.to_html(index=False,float_format=lambda x:f"{x:.4f}")+"""<p>源验证反复使用且只有4人，所有结果为探索性。下一步在4名源控制器人员上独立检查冷启动写入的未来收益，再考虑完整在线适应。早期失败的锁定主检验不被此分支替换。</p><a href="protocol.json">协议</a> · <a href="zero_control_audit.json">零权重梯度审计</a></html>""";(o/"report.html").write_text(html);print(summary.to_string(index=False))
